/**
 * Fetch / RFC 9110 header-name token. HTTP/2 pseudo-headers (`:method`,
 * `:path`, `:authority`, `:scheme`) fail this and throw in `Headers.append`.
 */
const FETCH_HEADER_NAME = /^[A-Za-z0-9!#$%&'*+\-.^_`|~]+$/;
function isFetchHeaderName(name) {
    return FETCH_HEADER_NAME.test(name);
}
/**
 * Copy Node incoming headers into a Fetch `Headers` object, dropping names
 * the Fetch API rejects (HTTP/2 pseudo-headers and any other illegal token).
 * Real headers are unchanged.
 */
export function incomingHeadersToFetch(headers) {
    const out = new Headers();
    for (const [key, value] of Object.entries(headers)) {
        if (value === undefined || !isFetchHeaderName(key)) {
            continue;
        }
        if (Array.isArray(value)) {
            for (const item of value) {
                out.append(key, item);
            }
        }
        else {
            out.set(key, value);
        }
    }
    return out;
}
function firstHeaderValue(value) {
    if (value === undefined) {
        return undefined;
    }
    return Array.isArray(value) ? value[0] : value;
}
/** HTTP/1 `Host`, or HTTP/2 `:authority` when Host was not copied. */
export function incomingRequestHost(headers, fallback = "127.0.0.1") {
    return firstHeaderValue(headers.host) ?? firstHeaderValue(headers[":authority"]) ?? fallback;
}
